sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
  try {
    var result;
    var __result = (function() {
      var n='x_snc_sas_positi_0_x_snc_red_folder_type';var out=[];
      var d=new GlideRecord('sys_dictionary');d.addQuery('name',n);d.query();out.push('dict:'+d.getRowCount());
      var a=new GlideRecord('sys_security_acl');a.addQuery('name','STARTSWITH',n);a.query();out.push('acl:'+a.getRowCount());
      var r=new GlideRecord('sys_user_role');r.addQuery('name','CONTAINS','red_folder');r.query();while(r.next())out.push('role:'+r.name+' '+r.sys_id);
      var mn=new GlideRecord('sys_app_application');mn.addQuery('title','CONTAINS','Red Folder');mn.query();while(mn.next())out.push('menu:'+mn.title+' '+mn.sys_id);
      gs.print(out.join(' | '));
      ; if (typeof result !== 'undefined') return result;
    })();
    response.setBody({ success: true, result: (__result === undefined ? null : __result) });
  } catch(e) {
    response.setBody({ success: false, error: e + '', message: e.message || (e + '') });
  }
})(request, response);
